import {createClient} from '@/lib/supabase/server';import {getWorkspaceContext} from '@/lib/workspace';import {createVendor} from '@/app/actions/procurement';import Link from 'next/link';
export default async function VendorsPage(){const ctx=await getWorkspaceContext();const supabase=await createClient();let vendors:any[]=[];if(ctx?.organization){const {data}=await supabase.from('vendors').select('*').eq('organization_id',ctx.organization.id).order('name');vendors=data??[];}
return <main className="min-h-screen bg-slate-50 p-5 md:p-10"><div className="max-w-6xl mx-auto"><Link href="/" className="text-blue-700 text-sm">← Dashboard</Link><h1 className="text-2xl font-bold mt-4">Vendor Directory</h1><p className="text-slate-500 mt-1">Maintain approved suppliers for purchasing.</p><div className="grid lg:grid-cols-3 gap-5 mt-6"><section className="bg-white border rounded-2xl p-5"><h2 className="font-semibold">Add vendor</h2><form action={async (formData: FormData) => { await createVendor(formData); }} className="space-y-3 mt-4"><input name="name" required placeholder="Vendor / company name" className="w-full border rounded-lg p-2.5"/><input name="contact_name" placeholder="Contact person" className="w-full border rounded-lg p-2.5"/><input name="email" type="email" placeholder="Email" className="w-full border rounded-lg p-2.5"/><input name="phone" placeholder="Phone" className="w-full border rounded-lg p-2.5"/><input name="tax_id" placeholder="Tax ID / TIN" className="w-full border rounded-lg p-2.5"/><input name="payment_terms" defaultValue="Net 30" placeholder="Payment terms" className="w-full border rounded-lg p-2.5"/><textarea name="address" rows={2} placeholder="Address" className="w-full border rounded-lg p-2.5"/><button className="bg-blue-600 text-white rounded-lg px-4 py-2.5 text-sm font-semibold">Save vendor</button></form></section><section className="lg:col-span-2 bg-white border rounded-2xl overflow-hidden"><div className="p-4 border-b font-semibold">Vendors ({vendors.length})</div><div className="overflow-x-auto"><table className="w-full text-sm min-w-[600px]"><thead className="bg-slate-50"><tr><th className="text-left p-3">Vendor</th><th className="text-left p-3">Contact</th><th className="text-left p-3">Payment terms</th><th className="text-left p-3">Status</th></tr></thead><tbody>{vendors.map(v=><tr key={v.id} className="border-t"><td className="p-3 font-medium">{v.name}<div className="text-xs text-slate-500">{v.email??'—'}</div></td><td className="p-3">{v.contact_name??'—'}<div className="text-xs text-slate-500">{v.phone??''}</div></td><td className="p-3">{v.payment_terms??'—'}</td><td className="p-3"><span className="rounded-full bg-emerald-50 text-emerald-700 px-2 py-1">{v.status}</span></td></tr>)}{!vendors.length&&<tr><td colSpan={4} className="p-8 text-center text-slate-500">No vendors yet. Add your first vendor.</td></tr>}</tbody></table></div></section></div></div></main>}
